-- LD-053 (WP3; requirements section 18; docs/design/LD-DOC-05 section 5): requests for statements and documents that
-- the legal department addresses to the authority's own units, their replies and their follow-up. Additive only.

create sequence info_request_no_seq;

create table info_request (
    id                    uuid primary key default gen_random_uuid(),
    case_id               uuid          not null references legal_case (id),
    -- Generated by the system (IR-<year>-<number>); never typed.
    request_no            varchar(24)   not null constraint info_request_no_unique unique,
    -- The unit asked to reply (the authority's tree) and its name when the request was made; renaming the unit later
    -- does not rewrite the request.
    unit_id               uuid references org_unit (id),
    unit_name_snapshot    varchar(300),
    subject               varchar(300)  not null constraint info_request_subject_visible check (length(btrim(subject)) > 0),
    details               varchar(4000),
    required_documents    varchar(2000),
    drafted_on            date,
    sent_on               date,
    letter_no             varchar(100),
    letter_date           date,
    due_on                date,
    responsible_member_id uuid,
    addressee             varchar(200),
    notes                 varchar(2000),
    status                varchar(16)   not null default 'DRAFT' constraint info_request_status_known check (status in
        ('DRAFT', 'PENDING_APPROVAL', 'SENT', 'AWAITING', 'PARTIAL', 'INCOMPLETE', 'COMPLETE', 'OVERDUE', 'CLOSED')),
    -- OVERDUE is set by the follow-up run from SENT or AWAITING; this is where the request returns to if its due date
    -- moves forward again.
    status_before_overdue varchar(16),
    delay_reason          varchar(2000),
    close_reason          varchar(2000),
    closed_on             date,
    -- Reserved links to a fact or a defence of the case (WP2 tables); validated once those tables exist.
    linked_fact_id        uuid,
    linked_defense_id     uuid,
    version               bigint        not null default 0,
    created_at            timestamptz   not null default now(),
    created_by            uuid          not null,
    updated_at            timestamptz   not null default now(),
    updated_by            uuid          not null,
    constraint info_request_text_visible check (
        (details is null or length(btrim(details)) > 0) and (required_documents is null or length(btrim(required_documents)) > 0)
        and (notes is null or length(btrim(notes)) > 0) and (delay_reason is null or length(btrim(delay_reason)) > 0)),
    constraint info_request_closed_complete check ((status = 'CLOSED') = (closed_on is not null)),
    constraint info_request_overdue_origin check ((status = 'OVERDUE') = (status_before_overdue is not null))
);
create index info_request_case on info_request (case_id, created_at);
create index info_request_open_due on info_request (status, due_on);
create index info_request_unit on info_request (unit_id);

-- One row per reply: a request may have several, partial or incomplete ones (all kept, none overwritten).
create table info_reply (
    id                uuid primary key default gen_random_uuid(),
    request_id        uuid          not null references info_request (id),
    -- Repeats the request's case so lists and reports restrict to visible cases without a join.
    case_id           uuid          not null references legal_case (id),
    received_on       date          not null,
    completeness      varchar(10)   not null constraint info_reply_completeness_known
        check (completeness in ('PARTIAL', 'INCOMPLETE', 'COMPLETE')),
    summary           varchar(4000),
    -- The reply document archived in the case file (the document module); removing the document keeps the reply.
    document_id       uuid references case_document (id) on delete set null,
    linked_fact_id    uuid,
    linked_defense_id uuid,
    created_at        timestamptz   not null default now(),
    created_by        uuid          not null,
    constraint info_reply_summary_visible check (summary is null or length(btrim(summary)) > 0)
);
create index info_reply_request on info_reply (request_id, received_on);
create index info_reply_case on info_reply (case_id);

-- Follow-up: a reminder, a new letter to the unit, or an escalation to a named user. Dated, attributed, never edited.
create table info_follow_up (
    id           uuid primary key default gen_random_uuid(),
    request_id   uuid          not null references info_request (id),
    case_id      uuid          not null references legal_case (id),
    kind         varchar(12)   not null constraint info_follow_up_kind_known
        check (kind in ('REMINDER', 'RE_ADDRESS', 'ESCALATION')),
    on_date      date          not null,
    note         varchar(2000),
    escalated_to uuid,
    created_at   timestamptz   not null default now(),
    created_by   uuid          not null,
    constraint info_follow_up_escalation_target check ((kind = 'ESCALATION') = (escalated_to is not null)),
    constraint info_follow_up_note_visible check (note is null or length(btrim(note)) > 0)
);
create index info_follow_up_request on info_follow_up (request_id, on_date);
create index info_follow_up_case on info_follow_up (case_id);
